begin;
set local statement_timeout='20s';set local lock_timeout='3s';
do $$
declare actor uuid;rule_id uuid:=gen_random_uuid();item_id uuid:=gen_random_uuid();m date:=date_trunc('month',now() at time zone 'America/Belem')::date;e public.finance_expenses;old public.finance_expenses;rule public.finance_recurring_rules;n integer;result jsonb;
begin
 if private.finance_due_date('2027-02-01',31)<>'2027-02-28'::date or private.finance_due_date('2028-02-01',31)<>'2028-02-29'::date then raise exception 'FAIL February clamp';end if;
 if not exists(select 1 from storage.buckets where id='inventory-images' and not public and file_size_limit=5242880 and allowed_mime_types=array['image/jpeg','image/png','image/webp']) then raise exception 'FAIL bucket configuration';end if;
 select id into actor from public.profiles where role='administrador' limit 1;if actor is null then raise exception 'Admin fixture missing';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);execute 'set local role authenticated';
 result:=public.finance_command('create',jsonb_build_object('id',rule_id,'description','RECURRING_SYNTHETIC','amount',1000,'incurred_on',m,'recurring',true,'due_day',31,'end_month',(m+interval '4 months')::date,'notes','Synthetic only'));
 if (select count(*) from public.finance_expenses where recurrence_id=rule_id)<>5 then raise exception 'FAIL initial occurrences';end if;
 perform public.finance_command('create',jsonb_build_object('id',rule_id,'description','RECURRING_SYNTHETIC','amount',1000,'incurred_on',m,'recurring',true,'due_day',31));
 perform public.finance_command('sync','{}');if (select count(*) from public.finance_expenses where recurrence_id=rule_id)<>5 then raise exception 'FAIL duplicated months';end if;
 select * into e from public.finance_expenses where recurrence_id=rule_id and competency_month=m;
 perform public.finance_command('status',jsonb_build_object('id',e.id,'expected_updated_at',e.updated_at,'status','pago','paid_on',(now() at time zone 'America/Belem')::date));
 begin perform public.finance_command('status',jsonb_build_object('id',e.id,'expected_updated_at',e.updated_at,'status','pendente'));raise exception 'FAIL stale edit';exception when serialization_failure then null;end;
 select * into e from public.finance_expenses where recurrence_id=rule_id and competency_month=(m+interval '1 month')::date;
 perform public.finance_command('edit',jsonb_build_object('id',e.id,'expected_updated_at',e.updated_at,'description','ONE_MONTH_EXCEPTION','amount',1200,'incurred_on',e.incurred_on,'due_on',e.due_on,'scope','month'));
 if (select amount from public.finance_expenses where recurrence_id=rule_id and competency_month=(m+interval '2 months')::date)<>1000 then raise exception 'FAIL month edit affected future';end if;
 select * into e from public.finance_expenses where recurrence_id=rule_id and competency_month=(m+interval '2 months')::date;
 perform public.finance_command('edit',jsonb_build_object('id',e.id,'expected_updated_at',e.updated_at,'description','FOLLOWING_CHANGE','amount',1400,'incurred_on',e.incurred_on,'due_on',e.due_on,'due_day',31,'scope','following'));
 if (select amount from public.finance_expenses where recurrence_id=rule_id and competency_month=(m+interval '1 month')::date)<>1200 or (select amount from public.finance_expenses where recurrence_id=rule_id and competency_month=(m+interval '3 months')::date)<>1400 then raise exception 'FAIL following scope';end if;
 select * into e from public.finance_expenses where recurrence_id=rule_id and competency_month=(m+interval '1 month')::date;
 perform public.finance_command('edit',jsonb_build_object('id',e.id,'expected_updated_at',e.updated_at,'description','ALL_PENDING_CHANGE','amount',1600,'incurred_on',e.incurred_on,'due_on',e.due_on,'due_day',30,'scope','all_pending'));
 if exists(select 1 from public.finance_expenses where recurrence_id=rule_id and status='pendente' and amount<>1600) or (select amount from public.finance_expenses where recurrence_id=rule_id and status='pago')<>1000 then raise exception 'FAIL paid history or all pending';end if;
 select * into e from public.finance_expenses where recurrence_id=rule_id and competency_month=(m+interval '1 month')::date;
 perform public.finance_command('status',jsonb_build_object('id',e.id,'expected_updated_at',e.updated_at,'status','cancelado'));
 select * into rule from public.finance_recurring_rules where id=rule_id;
 perform public.finance_command('end',jsonb_build_object('id',rule_id,'expected_updated_at',rule.updated_at,'end_month',(m+interval '2 months')::date));
 if (select count(*) from public.finance_expenses where recurrence_id=rule_id and recurrence_canceled)<>2 then raise exception 'FAIL ending future';end if;
 select * into rule from public.finance_recurring_rules where id=rule_id;
 perform public.finance_command('end',jsonb_build_object('id',rule_id,'expected_updated_at',rule.updated_at,'end_month',null));
 if not exists(select 1 from public.finance_expenses where recurrence_id=rule_id and competency_month=(m+interval '1 month')::date and status='cancelado' and not recurrence_canceled) then raise exception 'FAIL individual cancel not preserved';end if;
 if not exists(select 1 from public.finance_expenses where recurrence_id=rule_id and competency_month=(m+interval '5 months')::date and amount=1600 and extract(day from due_on)=30) then raise exception 'FAIL future generation changed version';end if;
 select * into e from public.finance_expenses where recurrence_id=rule_id and status='pago';
 begin perform public.finance_command('edit',jsonb_build_object('id',e.id,'expected_updated_at',e.updated_at,'description','DO_NOT_CHANGE_PAID','amount',1,'incurred_on',e.incurred_on,'scope','month'));raise exception 'FAIL paid edit accepted';exception when others then if sqlerrm not like 'Reabra a despesa%' then raise;end if;end;
 begin insert into public.finance_expenses(description,amount,created_by) values('DIRECT_BYPASS',1,actor);raise exception 'FAIL direct write';exception when insufficient_privilege then null;end;
 insert into public.inventory_items(id,name) values(item_id,'PHOTO_SYNTHETIC');
 update public.inventory_items set image_path=item_id::text||'/'||gen_random_uuid()::text||'.jpg' where id=item_id;
 begin update public.inventory_items set image_path='https://invalid.example/image.svg' where id=item_id;raise exception 'FAIL unsafe photo path';exception when check_violation then null;end;
 begin update public.inventory_items set current_quantity=999 where id=item_id;raise exception 'FAIL direct stock balance edit';exception when insufficient_privilege then null;when others then if sqlerrm<>'Alteracao de saldo exige movimentacao' then raise;end if;end;
 execute 'reset role';
 select id into actor from public.profiles where role='visualizador' limit 1;
 if actor is not null then
  perform set_config('request.jwt.claim.sub',actor::text,true);execute 'set local role authenticated';
  begin perform public.finance_command('sync','{}');raise exception 'FAIL viewer finance command';exception when insufficient_privilege then null;end;
  if exists(select 1 from public.finance_recurring_rules where id=rule_id) then raise exception 'FAIL viewer sees rules';end if;execute 'reset role';
 end if;
 raise notice 'PASS recurring scopes, paid history, duplicate protection, clamps, cancellation/resume, concurrency, authorization and photo paths';
end $$;
rollback;
